from pwn import *
import string
import itertools

def xor_bytes(a, b):
    return bytes([x ^ y for x, y in zip(a, b)])

# Configure shorter timeout and multiple attempts
context.timeout = 3
MAX_ATTEMPTS = 15
REQUIRED_CIPHERTEXTS = 10

def get_ciphertexts():
    try:
        r = remote('crypto.chal.csaw.io', 1337)

        # Send seed (must be 16 bytes)
        r.recvuntil(b'Send me a random seed\n')
        r.sendline(b'1337'.ljust(16))

        # Get encrypted flag line
        data = r.recvuntil(b'Encrypted flag:\n')

        # Collect ciphertexts
        ciphertexts = []
        while len(ciphertexts) < REQUIRED_CIPHERTEXTS:
            try:
                ct = r.recvline().strip()
                if ct and len(ct) > 0:
                    ciphertexts.append(ct)
            except:
                break

        r.close()
        return ciphertexts
    except:
        return []

# Try multiple times to get ciphertexts
all_ciphertexts = []
for attempt in range(MAX_ATTEMPTS):
    print(f"\nAttempt {attempt + 1}/{MAX_ATTEMPTS}")
    cts = get_ciphertexts()
    if len(cts) >= REQUIRED_CIPHERTEXTS:
        all_ciphertexts.extend(cts)
        if len(all_ciphertexts) >= REQUIRED_CIPHERTEXTS * 2:
            break

if len(all_ciphertexts) < REQUIRED_CIPHERTEXTS:
    print("Failed to get enough ciphertexts")
    exit(1)

print(f"\nCollected {len(all_ciphertexts)} ciphertexts")
print(f"First ciphertext length: {len(all_ciphertexts[0])} bytes")

# Split ciphertexts into blocks
BLOCK_SIZE = 16
known_prefix = b"Encrypted Flag: "

def split_blocks(ct):
    return [ct[i:i+BLOCK_SIZE] for i in range(0, len(ct), BLOCK_SIZE)]

# XOR analysis with improved pattern matching
def is_printable(s):
    return all(32 <= c <= 126 for c in s)

def score_text(text):
    score = 0
    if 'flag{' in text.lower():
        score += 10
    if '}' in text:
        score += 5
    if any(c.isalnum() for c in text):
        score += 3
    for c in text:
        if c in string.ascii_letters + string.digits:
            score += 1
    return score

# Store results with scores
scored_results = []

# Analyze each pair of ciphertexts
for ct1, ct2 in itertools.combinations(all_ciphertexts[:REQUIRED_CIPHERTEXTS], 2):
    # XOR the ciphertexts
    xored = xor_bytes(ct1, ct2)

    # Split into blocks
    blocks = split_blocks(xored)

    # Known plaintext XOR for first block
    first_block = blocks[0]
    known_xor = xor_bytes(first_block, known_prefix)

    # Try to recover each block
    for block_idx, block in enumerate(blocks[1:], 1):
        try:
            # Try each possible rotation and XOR combination
            for offset in range(len(block)):
                test_block = block[offset:] + block[:offset]
                possible_plain = xor_bytes(test_block, known_xor)

                if is_printable(possible_plain):
                    decoded = possible_plain.decode('ascii', errors='ignore')
                    score = score_text(decoded)
                    if score > 0:
                        scored_results.append((score, decoded))
        except:
            continue

print("\nPotential flag fragments (sorted by likelihood):")
seen = set()
for score, text in sorted(scored_results, key=lambda x: x[0], reverse=True):
    if text not in seen and score >= 3:
        print(f"[+] (Score: {score:2d}) {repr(text)}")
        seen.add(text)
        if len(seen) >= 20:  # Limit output to top 20 results
            break

